// Reshape a Shopify orders-export CSV (one row per line item) into
// raw_shopify_orders shape. Input: rows from "Parse CSV". Output: one item per order.

const CLIENT_ID = 'dobias';
const INGESTED_AT = new Date().toISOString().slice(0, 19).replace('T', ' ');

const num = v => {
  if (v === null || v === undefined || v === '') return 0;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? 0 : n;
};

// Shopify CSV timestamps: "2024-05-01 12:30:00 -0400" -> BQ "YYYY-MM-DD HH:MM:SS" (UTC)
const fmtTs = v => {
  if (!v) return null;
  const d = new Date(v);
  return isNaN(d.getTime()) ? null : d.toISOString().slice(0, 19).replace('T', ' ');
};

const ORDER_FIELDS = ['Name','Email','Financial Status','Paid at','Fulfillment Status',
  'Currency','Subtotal','Shipping','Taxes','Total','Discount Amount','Created at',
  'Shipping Province','Shipping Country','Cancelled at','Source','Id'];

// Group flat rows into orders, keyed by "Name" (repeated on every line-item row).
const orders = {};
for (const item of $input.all()) {
  const r = item.json;
  const key = r['Name'];
  if (!key) continue;
  if (!orders[key]) orders[key] = { h: {}, rows: [] };
  const h = orders[key].h;
  for (const f of ORDER_FIELDS) {
    if ((h[f] === undefined || h[f] === '') && r[f] !== undefined && r[f] !== '') h[f] = r[f];
  }
  orders[key].rows.push(r);
}

return Object.values(orders).map(({ h, rows }) => {
  const createdAt = fmtTs(h['Created at']);
  return {
    json: {
      client_id:             CLIENT_ID,
      ingested_at:           INGESTED_AT,
      ingest_source:         'manual_csv',

      order_id:              String(h['Id'] ?? ''),
      order_number:          h['Name'] ?? '',
      order_date:            createdAt ? createdAt.slice(0, 10) : null,
      created_at:            createdAt,
      updated_at:            null,
      processed_at:          fmtTs(h['Paid at']),

      currency:              h['Currency'] ?? '',
      presentment_currency:  h['Currency'] ?? '',
      subtotal_price:        num(h['Subtotal']),
      total_shipping:        num(h['Shipping']),
      total_tax:             num(h['Taxes']),
      total_discounts:       num(h['Discount Amount']),
      total_price:           num(h['Total']),

      customer_id:           '',
      customer_email:        h['Email'] ?? '',
      is_returning_customer: null,
      shipping_country:      h['Shipping Country'] ?? '',
      shipping_province:     h['Shipping Province'] ?? '',

      financial_status:      h['Financial Status'] ?? '',
      fulfillment_status:    h['Fulfillment Status'] ?? '',
      cancelled_at:          fmtTs(h['Cancelled at']),
      source_name:           h['Source'] ?? '',

      line_items: JSON.stringify(
        rows.filter(r => (r['Lineitem name'] ?? '') !== '').map(r => ({
          line_item_id:       '',
          product_id:         '',
          variant_id:         '',
          sku:                r['Lineitem sku'] ?? '',
          title:              r['Lineitem name'] ?? '',
          quantity:           num(r['Lineitem quantity']),
          price:              num(r['Lineitem price']),
          total_discount:     num(r['Lineitem discount']),
          fulfillment_status: r['Lineitem fulfillment status'] ?? null
        }))
      ),

      payload_json:          JSON.stringify(rows)
    }
  };
});
